#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

struct Node { int value; struct Node *next; };

static bool push_front(struct Node **head, int value)
{
    if (head == NULL) return false;
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) return false;
    node->value = value;
    node->next = *head;
    *head = node;
    return true;
}

static bool remove_first(struct Node **head, int target)
{
    if (head == NULL) return false;
    struct Node **link = head;
    while (*link != NULL && (*link)->value != target) {
        link = &(*link)->next;
    }
    if (*link == NULL) return false;
    struct Node *removed = *link;
    *link = removed->next;
    free(removed);
    return true;
}

static void print_list(const struct Node *head)
{
    for (const struct Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    putchar('\n');
}

static void destroy_list(struct Node **head)
{
    if (head == NULL) return;
    while (*head != NULL) {
        struct Node *next = (*head)->next;
        free(*head);
        *head = next;
    }
}

int main(void)
{
    struct Node *head = NULL;
    if (!push_front(&head, 30) || !push_front(&head, 20) || !push_front(&head, 10)) {
        destroy_list(&head);
        return 1;
    }
    print_list(head);
    if (!remove_first(&head, 20)) {
        destroy_list(&head);
        return 2;
    }
    print_list(head);
    (void)remove_first(&head, 99);
    destroy_list(&head);
    return 0;
}

#include <stdio.h>

struct Node { int value; const struct Node *next; };

static void print_values(const struct Node *head)
{
    const struct Node *current = head;
    while (current != NULL) {
        printf("%d\n", current->value);
        current = current->next;
    }
}

int main(void)
{
    const struct Node third = {30, NULL};
    const struct Node second = {20, &third};
    const struct Node first = {10, &second};
    print_values(&first);
    return 0;
}
